@namespace sv_325d4d25a3c84544b55718fa26d3eba9.Components.Pages.Settings
@using sv_325d4d25a3c84544b55718fa26d3eba9.Services
@inject ISettingsService SettingsService

<div class="settings-section appearance-section">
    <h2>Appearance</h2>

    @if (_loading)
    {
        <p>Loading appearance settings...</p>
    }
    else
    {
        <!-- Theme Selector -->
        <div class="form-group">
            <label>Theme</label>
            <div class="radio-group">
                <label><input type="radio" name="theme" value="Light" @onchange="() => _theme = &quot;Light&quot;" checked="@(_theme == "Light")" /> Light</label>
                <label><input type="radio" name="theme" value="Dark" @onchange="() => _theme = &quot;Dark&quot;" checked="@(_theme == "Dark")" /> Dark</label>
                <label><input type="radio" name="theme" value="System" @onchange="() => _theme = &quot;System&quot;" checked="@(_theme == "System")" /> System</label>
            </div>
        </div>

        <!-- Font Size Selector -->
        <div class="form-group">
            <label>Font Size</label>
            <div class="radio-group">
                <label><input type="radio" name="fontSize" value="Small" @onchange="() => _fontSize = &quot;Small&quot;" checked="@(_fontSize == "Small")" /> Small</label>
                <label><input type="radio" name="fontSize" value="Medium" @onchange="() => _fontSize = &quot;Medium&quot;" checked="@(_fontSize == "Medium")" /> Medium</label>
                <label><input type="radio" name="fontSize" value="Large" @onchange="() => _fontSize = &quot;Large&quot;" checked="@(_fontSize == "Large")" /> Large</label>
            </div>
        </div>

        <!-- Language Dropdown -->
        <div class="form-group">
            <label for="language">Language</label>
            <select id="language" @bind="_language">
                <option value="en">English</option>
                <option value="es">Spanish</option>
                <option value="fr">French</option>
                <option value="de">German</option>
                <option value="ja">Japanese</option>
            </select>
        </div>

        <!-- Compact Mode Toggle -->
        <div class="form-group">
            <label class="toggle-item">
                <input type="checkbox" @bind="_compactMode" />
                <span>Compact Mode</span>
            </label>
        </div>

        <!-- Live Preview -->
        <div class="live-preview @GetPreviewClasses()">
            <h4>Preview</h4>
            <p>This is how your content will look with the selected settings.</p>
            <div class="preview-card">
                <p><strong>Sample Card</strong></p>
                <p>Lorem ipsum dolor sit amet, consectetur adipiscing elit.</p>
            </div>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAppearance">Save</button>
        </div>

        @if (!string.IsNullOrEmpty(_message))
        {
            <div class="toast-message success">@_message</div>
        }
    }
</div>

@code {
    private bool _loading = true;
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private string _message = "";

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{_theme.ToLowerInvariant()} font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _message = "Appearance settings saved!";
    }
}

@page "/settings"
@namespace sv_325d4d25a3c84544b55718fa26d3eba9.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionSelected="SetActiveSection" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        _activeSection = section;
    }
}

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    overflow-y: auto;
}

/* Sidebar */
::deep .settings-sidebar {
    width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1rem 0;
}

::deep .settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

::deep .settings-sidebar li {
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    font-weight: 500;
    color: #495057;
    transition: background-color 0.15s, color 0.15s;
}

::deep .settings-sidebar li:hover {
    background: #e9ecef;
}

::deep .settings-sidebar li.active {
    background: #0d6efd;
    color: #fff;
}

/* Section Styles */
::deep .settings-section {
    max-width: 700px;
}

::deep .settings-section h2 {
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #212529;
}

::deep .form-group {
    margin-bottom: 1rem;
}

::deep .form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
    color: #495057;
}

::deep .form-group input[type="text"],
::deep .form-group input[type="email"],
::deep .form-group input[type="password"],
::deep .form-group textarea,
::deep .form-group select {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 0.375rem;
    font-size: 1rem;
}

::deep .form-group textarea {
    resize: vertical;
}

/* Buttons */
::deep .button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

::deep .btn-primary {
    background: #0d6efd;
    color: #fff;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 0.375rem;
    cursor: pointer;
    font-weight: 500;
}

::deep .btn-primary:hover {
    background: #0b5ed7;
}

::deep .btn-secondary {
    background: #6c757d;
    color: #fff;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 0.375rem;
    cursor: pointer;
    font-weight: 500;
}

::deep .btn-secondary:hover {
    background: #5c636a;
}

::deep .btn-danger {
    background: #dc3545;
    color: #fff;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 0.375rem;
    cursor: pointer;
    font-weight: 500;
}

::deep .btn-danger:hover {
    background: #bb2d3b;
}

::deep .btn-small {
    padding: 0.25rem 0.75rem;
    font-size: 0.875rem;
}

/* Toast Messages */
::deep .toast-message {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    font-weight: 500;
}

::deep .toast-message.success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

::deep .toast-message.error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

/* Avatar */
::deep .avatar-preview {
    margin-bottom: 1.5rem;
    text-align: center;
}

::deep .avatar-image {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #dee2e6;
}

::deep .avatar-url {
    margin-top: 0.5rem;
    font-size: 0.875rem;
    color: #6c757d;
    word-break: break-all;
}

/* Toggles */
::deep .toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    margin-bottom: 1.5rem;
}

::deep .toggle-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

::deep .toggle-item input[type="checkbox"] {
    width: 1.25rem;
    height: 1.25rem;
}

/* Channels */
::deep .channels-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-bottom: 1rem;
}

::deep .channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

/* Expandable Panel */
::deep .expandable-panel {
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    margin-bottom: 1.5rem;
}

::deep .panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-weight: 500;
    font-size: 1rem;
}

::deep .panel-header:hover {
    background: #e9ecef;
}

::deep .panel-body {
    padding: 1rem;
    border-top: 1px solid #dee2e6;
}

/* Two-Factor */
::deep .two-factor-section {
    margin-bottom: 1.5rem;
}

::deep .status-row {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

::deep .status-indicator {
    font-weight: 600;
}

::deep .status-indicator.enabled {
    color: #198754;
}

::deep .status-indicator.disabled {
    color: #dc3545;
}

::deep .info-text {
    margin-top: 0.5rem;
    font-size: 0.875rem;
    color: #6c757d;
}

/* Sessions Table */
::deep .sessions-section {
    margin-bottom: 1.5rem;
}

::deep .sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.75rem;
}

::deep .sessions-table th,
::deep .sessions-table td {
    padding: 0.75rem;
    text-align: left;
    border-bottom: 1px solid #dee2e6;
}

::deep .sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
}

::deep .current-badge {
    font-size: 0.75rem;
    background: #e2e3e5;
    color: #41464b;
    padding: 0.2rem 0.5rem;
    border-radius: 0.25rem;
}

/* Modal */
::deep .modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

::deep .modal-dialog {
    background: #fff;
    padding: 1.5rem;
    border-radius: 0.5rem;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
}

::deep .modal-dialog h4 {
    margin-top: 0;
}

/* Radio Groups */
::deep .radio-group {
    display: flex;
    gap: 1.5rem;
    margin-top: 0.25rem;
}

::deep .radio-group label {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    font-weight: normal;
    cursor: pointer;
}

/* Live Preview */
::deep .live-preview {
    margin-top: 1.5rem;
    padding: 1.5rem;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    transition: all 0.2s;
}

::deep .live-preview.theme-dark {
    background: #212529;
    color: #f8f9fa;
    border-color: #495057;
}

::deep .live-preview.theme-light {
    background: #ffffff;
    color: #212529;
}

::deep .live-preview.theme-system {
    background: #f0f0f0;
    color: #333;
}

::deep .live-preview.font-small {
    font-size: 0.85rem;
}

::deep .live-preview.font-medium {
    font-size: 1rem;
}

::deep .live-preview.font-large {
    font-size: 1.2rem;
}

::deep .live-preview.compact {
    padding: 0.75rem;
    line-height: 1.2;
}

::deep .preview-card {
    margin-top: 0.75rem;
    padding: 0.75rem;
    border: 1px solid currentColor;
    border-radius: 0.375rem;
    opacity: 0.8;
}

